/**
 * Jinx Boffin + Politician: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Boffin
 * Wiki: https://wiki.bloodontheclocktower.com/Politician
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import type { Script } from '#lib/core/data/index.ts';
import { castWith, codes, run } from '#lib/core/model/fixtures.test-support.ts';
import { scriptCharacterIds } from '#lib/core/model/characters.ts';
import { barredAbilities, jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';

describe('Boffin + Politician jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'boffin', 'politician');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('boffin')?.name).toBe('Boffin');
		expect(data.byId.get('politician')?.name).toBe('Politician');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['boffin', 'politician'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['boffin'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['politician'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Boffin cannot give the Demon the Politician ability.
	describe('the Boffin cannot give the Demon the Politician ability', () => {
		const script: Script = {
			meta: { name: 'Jinxed' },
			entries: ['boffin', 'imp', 'politician', 'chef', 'empath', 'monk', 'saint'].map((id) => ({
				kind: 'official' as const,
				id
			}))
		};
		const cast = castWith({ script });

		it("is data in the Boffin's rules", () => {
			expect(jinxRulesBetween('boffin', 'politician')).toEqual({ notGiven: true });
		});

		it('leaves the Politician out of the abilities the Boffin may give', () => {
			expect(barredAbilities('boffin', scriptCharacterIds(script))).toEqual(['politician']);
			expect(barredAbilities('boffin', ['boffin', 'chef'])).toEqual([]);
		});

		it('warns, but still lets the Storyteller give it', () => {
			const { session, ctx, seats } = cast(['boffin', 'imp', 'monk', 'empath', 'saint']);
			const given = run(session, ctx, {
				type: 'SetHeldAbility',
				seatId: seats[1],
				via: 'boffin',
				characterId: 'politician'
			});
			expect(codes(given)).toEqual(['jinxed-ability']);
			expect(given.game.seats[seats[1]].abilities).toEqual([
				{ characterId: 'politician', via: 'boffin' }
			]);
			const chef = run(session, ctx, {
				type: 'SetHeldAbility',
				seatId: seats[1],
				via: 'boffin',
				characterId: 'chef'
			});
			expect(codes(chef)).toEqual([]);
		});
	});
});
